pub fn remove_from_payload_head(&mut self, size: usize) -> Result<()> {
        unsafe {
            let src = self.data_base();
            let dst = src.offset(size as isize);
            ptr::copy_nonoverlapping(src, dst, size);
            (*self.mbuf).remove_data_beginning(size);
            Ok(())
        }
    }

    /// Add data to the head of the payload.
    #[inline]
    pub fn add_to_payload_head(&mut self, size: usize) -> Result<()> {
        unsafe {
            let added = (*self.mbuf).add_data_end(size);
            if added >= size {
                let src = self.payload();
                let dst = src.offset(size as isize);
                ptr::copy_nonoverlapping(src, dst, size);
                Ok(())
            } else {
                Err(ErrorKind::FailedAllocation.into())
            }
        }
    }

pub fn data_u16_to_gpu(
    &self,
    data: *const u16,
    data_layout: Layout,
    nitems: usize,
    rows: i64,
    cols: i64,
    cols_capacity: i64,
) -> Result<OpenCLTensor, OpenCLError> {
    unsafe {
        let buf = Buffer::builder()
            .queue(self.queue.clone())
            .len(nitems)
            .build()?;
        let mut event = Event::empty();
        let data_slice: &[u16] = std::slice::from_raw_parts(data, nitems);
        buf.cmd()
            .write(data_slice)
            .block(false)
            .enew(&mut event)
            .enq()?;
        Ok(OpenCLTensor {
            buf,
            initial_write_event: Some(event),
            last_event: None,
            data,
            data_layout,
            nitems,
            rows,
            cols,
            cols_capacity,
            queue: self.queue.clone(),
            cl: self.clone(),
        })
    }
}

