fn raw_cksum<T>(buf: *const T, len: usize) -> u16 {
    let mut sum = Wrapping(0);
    let mut remaining_len = len;
    let mut ptr = buf as *const u16;
    while remaining_len >= 2 {
        unsafe {
            sum += Wrapping(*ptr);
            ptr = ptr.offset(1);
        }
        remaining_len -= 2;
    }
    if remaining_len == 1 {
        unsafe {
            sum += Wrapping(*(ptr as *const u8) as u16);
        }
    }
    sum.0
}

