pub fn from_parent_child(hist_tree: &[NodeHistogram], root_num: usize, child_num: usize, update_num: usize) {
    unsafe {
        let root_hist = &hist_tree.get_unchecked(root_num).data;
        let child_hist = &hist_tree.get_unchecked(child_num).data;
        let update_hist = &hist_tree.get_unchecked(update_num).data;

        root_hist
            .iter()
            .zip(child_hist.iter())
            .zip(update_hist.iter())
            .for_each(|((root_feat_hist, child_feat_hist), update_feat_hist)| {
                root_feat_hist
                    .data
                    .iter()
                    .zip(child_feat_hist.data.iter())
                    .zip(update_feat_hist.data.iter())
                    .for_each(|((root_bin, child_bin), update_bin)| {
                        Bin::from_parent_child(root_bin.get(), child_bin.get(), update_bin.get())
                    })
            });
    }
}

pub fn from_parent_two_children(
    hist_tree: &[NodeHistogram],
    root_num: usize,
    first_num: usize,
    second_num: usize,
    update_num: usize,
) {
    unsafe {
        let root_hist = &hist_tree.get_unchecked(root_num).data;
        let first_hist = &hist_tree.get_unchecked(first_num).data;
        let second_hist = &hist_tree.get_unchecked(second_num).data;
        let update_hist = &hist_tree.get_unchecked(update_num).data;

        root_hist
            .iter()
            .zip(first_hist.iter())
            .zip(second_hist.iter())
            .zip(update_hist.iter())
            .for_each(
                |(((root_feat_hist, first_feat_hist), second_feat_hist), update_feat_hist)| {
                    root_feat_hist
                        .data
                        .iter()
                        .zip(first_feat_hist.data.iter())
                        .zip(second_feat_hist.data.iter())
                        .zip(update_feat_hist.data.iter())
                        .for_each(|(((root_bin, first_bin), second_bin), update_bin)| {
                            Bin::from_parent_two_children(
                                root_bin.get(),
                                first_bin.get(),
                                second_bin.get(),
                                update_bin.get(),
                            )
                        })
                },
            );
    }
}

fn maybe_add_value(
    &mut self,
    parser: &Parser<Chars>,
    code: char,
    value: &[u8],
) -> Result<(), Error> {
    match self.extract_key(parser.stack().top()) {
        ObjectKeyTypes::Id => {
            if code != 's' && self.kb.kp_segments_len() == 1 {
                return Err(
                    Error::Shred(
                        "Expected string for `_id` field, got another type".to_string(),
                    ),
                );
            }
            self.doc_id = Some(unsafe { str::from_utf8_unchecked(value) }.to_string());
            self.kb.pop_object_key();
            self.kb.push_object_key("_id");
            *self.object_keys_indexed.last_mut().unwrap() = true;
            self.add_value(code, value)?;
        }
        ObjectKeyTypes::Key(key) => {
            if key == "type" {
                let is_valid_type = GEOJSON_TYPES
                    .iter()
                    .position(|&tt| tt == unsafe { str::from_utf8_unchecked(value) });
                if is_valid_type.is_some() {
                    self.maybe_geometry += 1;
                }
            }
            self.kb.pop_object_key();
            self.kb.push_object_key(&key);
            *self.object_keys_indexed.last_mut().unwrap() = true;
            self.add_value(code, value)?;
        }
        ObjectKeyTypes::NoKey => {
            self.add_value(code, value)?;
            self.kb.inc_top_array_index();
        }
    }
    Ok(())
}

