pub fn read_data(data: &mut Vec<i64>, encoded_data: &[u8], index: &mut usize) {
        let length = data.len();
        if length > 0 {
            data.clear();
            let ptr = encoded_data[*index..].as_ptr() as *mut i64;

            let v = unsafe { Vec::from_raw_parts(ptr, length, length) };
            let _ = v.iter().map(|&x| data.push(x)).collect::<()>();
            v.into_raw_parts();
            *index += length << 3;
        }
    }

